import logging


from taf.converters.base.interface import base
from .factory import TwDecoderConverterFactory

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class twdecoder(base):
    ROBOT_LIBRARY_SCOPE = "TEST SUITE"
    _factory = TwDecoderConverterFactory()

    def create_twdecoder_converter(self,
                                   name,
                                   input_file_path,
                                   tti_trace_decoder_options=None,
                                   tti_dec_bin_path=None,
                                   tti_dec_venv_path=None,
                                   stdout_path=None,
                                   stderr_path=None):

        """
        Create a converter to convert a TTI Trace pcap file to a directory of parquet files or parquetCsv output.

        Read a TTI Trace pcap file and convert it to parquet or parquetCsv format using TtiTraceDecoder.py script
        from the tti-dec toolchain. An output directory with default name "parq" will be created where the parquet
        files will be stored.


        :param name: name of the converter
        :param input_file_path: input .pcap file path
        :param Optional[str] tti_trace_decoder_options: additional options to be passed to TtiTraceDecoder.py script,
            default is 'parquet'
        :param Optional[str] tti_dec_bin_path:
            path where tti-dec binaries and scripts are installed, default is "/opt/tti-dec/tti-dec-bin"
        :param Optional[str] tti_dec_venv_path:
            path of virtualenv to be used for tti-dec Python scripts, default is "/opt/tti-dec/venv"
        :param Optional[str] stdout_path: path to write the standard output of the conversion command, default is None
        :param Optional[str] stderr_path: path to write the standard error of the conversion command, default is None

        """

        logger.info("Creating Converter with alias name " + name)
        configuration = {"input_file_path": input_file_path}
        for parameter_name, parameter_value in locals().items():
            if parameter_name in [
                "tti_dec_bin_path",
                "tti_dec_venv_path",
                "tti_trace_decoder_options",
                "stdout_path",
                "stderr_path",
            ]:
                if parameter_value is not None:
                    configuration[parameter_name] = parameter_value

        converter = self._factory.create(
            configuration=configuration,
            existing_arguments={})
        logger.info(name + " converter created successfully")
        self.set_alias(name, converter)
